-- Hosted migration roles do not include the extensions schema in search_path. Recreate functions
-- already deployed by earlier migrations with schema-qualified pgcrypto calls.
create or replace function public.create_club(p_name text,p_slug text,p_timezone text,p_idempotency_key uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_actor uuid:=public.current_player_id();v_club uuid;begin if v_actor is null then raise exception using errcode='P0001',detail='AUTH_REQUIRED';end if;insert into private.idempotency_commands(actor_id,operation,key,request_hash)values(v_actor,'create_club',p_idempotency_key,encode(extensions.digest(concat_ws('|',p_name,p_slug,p_timezone),'sha256'),'hex'))on conflict(actor_id,operation,key)do update set key=excluded.key returning (response->>'clubId')::uuid into v_club;if v_club is not null then return v_club;end if;insert into public.clubs(name,slug,timezone)values(trim(p_name),lower(trim(p_slug)),p_timezone)returning id into v_club;insert into public.club_memberships(club_id,player_id,role)values(v_club,v_actor,'owner');update private.idempotency_commands set response=jsonb_build_object('clubId',v_club)where actor_id=v_actor and operation='create_club' and key=p_idempotency_key;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id)values(auth.uid(),'club.created','club',v_club,v_club);return v_club;end$$;

create or replace function public.attest_player_identity(p_club_id uuid,p_player_id uuid,p_attestation_type text,p_note text,p_idempotency_key uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_id uuid; begin if not private.has_club_role(p_club_id,array['owner','score_official']::public.club_role[]) then raise exception using errcode='P0001',detail='PERMISSION_DENIED'; end if; insert into private.idempotency_commands(actor_id,operation,key,request_hash) values(public.current_player_id(),'attest_player_identity',p_idempotency_key,encode(extensions.digest(concat_ws('|',p_club_id,p_player_id,p_attestation_type,coalesce(p_note,'')),'sha256'),'hex')) on conflict(actor_id,operation,key) do nothing; insert into public.identity_attestations(club_id,player_id,attested_by_player_id,attestation_type,note) values(p_club_id,p_player_id,public.current_player_id(),p_attestation_type,p_note) returning id into v_id; insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id) values(auth.uid(),'identity.attested','player',p_player_id,p_club_id); return v_id; end $$;
